import { _decorator, assetManager, Component, ImageAsset, Label, Node, Sprite, Texture2D, Event } from 'cc';
import { PlayerModule } from '../modules/PlayerModule';
import { BaseComponent } from '../framework/BaseComponent';
import { GUIShop } from '../modules/shop/UI/GUIShop';
const { ccclass, property } = _decorator;

@ccclass('SceneLobby')
export class SceneLobby extends BaseComponent {
    public lbUsername: Label;

    protected onLoad(): void {
        console.log("????ZX");
        this.init();
    }

    start() {
        console.log("Start SceneLobby");
        this.updateInfo();
    }

    update(deltaTime: number) {
        
    }

    updateInfo() {
        this.lbUsername = this.node.getChildByPath("nodeBottomLeft/nodeUserInfo/lbUsername").getComponent(Label);
        this.lbUsername.string = PlayerModule.getInstance().getUsername();

        const spAvatar = this.node.getChildByPath("nodeBottomLeft/nodeUserInfo/spAvatar").getComponent(Sprite);
        var avatarUrl = PlayerModule.getInstance().getAvatarUrl();
        console.log("avatar: ", avatarUrl);
    }

    onClickEvent(event: Event, customEventData: string) {
        super.onClickEvent(event,customEventData);
        const node = event.target as Node;
        switch (node) {
            case this._mapChildNode.get("btnShop"): 
                this._mapChildNode.get("guiShop").getComponent(GUIShop).show();
        }
    }
}


