import { _decorator, Component, Node, Event, Button, Prefab, resources, instantiate } from 'cc';
import { BaseGUI } from '../../../framework/BaseGUI';
import { NodeShopGold } from './NodeShopGold';
const { ccclass, property } = _decorator;

@ccclass('GUIShop')
export class GUIShop extends BaseGUI {
    // @property(Prefab)
	prefabShopGoldItem: Prefab;

    nodeShopGoldItems: NodeShopGold[];
    
    onClickEvent(event: Event, customEventData: string) {
        super.onClickEvent(event,customEventData);
        switch (event.target) {
            case this._mapChildNode.get("btnClose"):
                this.hide();
        }
    }
    
    onLoad(): void {
        this.init();
        this.loadPrefab();
    }

    loadPrefab() {
        resources.load("shop/prefabs/nodeShopGold", Prefab, (err: any, preFab) => {
            this.prefabShopGoldItem = preFab;
            this.initShopItems();
        });
    }

    initShopItems() {
        this.nodeShopGoldItems = new Array<NodeShopGold>();
        for (let i = 0; i < 8; ++i) {
            const price = i + 0.99;
            const gold = (1 + i) * 1000000;
            const item = instantiate(this.prefabShopGoldItem).getComponent(NodeShopGold);
            item.init();
            item.setIndex(i);
            item.setGoldValue(gold);
            item.setPrice(price);
            this._mapChildNode.get("loGold").addChild(item.node);
            this.nodeShopGoldItems.push(item);
        }
    }
}