import { _decorator, Component, Label, Node, resources, Sprite, SpriteFrame, EventTarget, Event } from 'cc';
import { BaseComponent } from '../../../framework/BaseComponent';
import { formatNumberFullSeparateThousand } from '../../../utils/Utils';
import { PaymentModule } from '../../payment/PaymentModule';
const { ccclass, property } = _decorator;

@ccclass('NodeShopGold')
export class NodeShopGold extends BaseComponent {
    _index: number;
    _goldValue: number;
    _price: number;
    
    setIndex(index: number) {
        this._index = index;
        resources.load("shop/textures/img_shop_gold_%id/spriteFrame".replace("%id",index.toString()), SpriteFrame, (err: any, spriteFrame) => {
            this._mapChildNode.get("spGold").getComponent(Sprite).spriteFrame = spriteFrame;
        });
    }

    setGoldValue(goldValue: number) {
        this._goldValue = goldValue;
        console.log("ZVAAA...", this._goldValue);
        console.log(this);
        this._mapChildNode.get("lbGold").getComponent(Label).string = formatNumberFullSeparateThousand(goldValue);
    }

    setPrice(price: number) {
        this._price = price;
        this._mapChildNode.get("lbPrice").getComponent(Label).string = "$" + price; 
    }

    onClickEvent(event: Event, customEventData: string) {
        // The event here is a Touch object, and you can get the send node of the event by event.target
        const node = event.target as Node;
        console.log("Buy Shop Gold: ", this._index, this._price, this._goldValue, node.name);
        PaymentModule.getInstance().buyGoldPack(this._price, this._goldValue);
    }
}


