import { GlobalVar } from "../../GlobalVar";

export class PaymentModule {
    public static _instance: PaymentModule;
    public static getInstance(): PaymentModule {
        if (!this._instance) {
            this._instance = new PaymentModule();
        }
        return this._instance;
    }

    buyGoldPack(price: number, goldValue: number) {
        const invoiceData = {
            paymentItem: 0,
            goldValue: goldValue,
        };

        let url = "";
        GlobalVar.client.http.post("/payment/createInvoiceLink", {
            body: { invoiceData: invoiceData },
        })
        .then(response => {
            console.log("Response: ", response.data);
            url = response.data;
            window.Telegram?.WebApp?.openInvoice(url, (status) => {
                if (status === "paid") {
                  console.log("Hello paided?");
                }
            });
        });        
    }
}