import { _decorator, Component, Node } from 'cc';
import { BaseComponent } from './BaseComponent';
const { ccclass, property } = _decorator;

@ccclass('BaseGUI')
export class BaseGUI extends BaseComponent {
    constructor() {
        super();
    }
    
    show() {
        this.node.active = true;
    }

    hide() {
        this.node.active = false;
    }
}