import { _decorator, Button, Component, EventHandler, Label, Node, Sprite, Event } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('BaseComponent')
export class BaseComponent extends Component {
    _deep: number = 3;
    _mapChildNode: Map<string,Node>;
    _mapChildComp: Map<string,Component>;
    clickEventHandler: EventHandler;
    constructor() {
        super();
        this.init();
    }

    init() {
        this._mapChildNode = new Map<string,Node>();
        this._mapChildComp = new Map<string,Component>();
        this.initClickEventHandler();
        this.initChildren();
    }

    initClickEventHandler() {
        this.clickEventHandler = new EventHandler();
        // This node is the node to which your event handler code component belongs
        this.clickEventHandler.target = this.node;
        // This is the script class name
        this.clickEventHandler.component = 'BaseComponent';
        this.clickEventHandler.handler = 'onClickEvent';
    }
    setDeep(deep: number) {
        this._deep = deep;
    }
    initChildren() {
        this.initChildByName(this.node, this._deep);
    }
    initChildByName(nodeIniting: Node, deep: number) {
        if (deep <= 0 || !nodeIniting) {
            return;
        }
        this._mapChildNode.set(nodeIniting.name,nodeIniting);
        this.initComp(nodeIniting);
        nodeIniting.children.forEach((child, index) => {
            this.initChildByName(child,deep - 1);
        });
    }
    initComp(nodeIniting: Node) {
        const nodeName = nodeIniting.name;
        if (nodeName.indexOf("lb") >= 0) {
            this._mapChildComp.set(nodeName,nodeIniting.getComponent(Label));
            console.log("SetComp: ", nodeName);
        }
        if (nodeName.indexOf("sp") >= 0) {
            this._mapChildComp.set(nodeName,nodeIniting.getComponent(Sprite));
        }
        if (nodeName.indexOf("btn") >= 0) {
            const button = nodeIniting.getComponent(Button);
            button.clickEvents.push(this.clickEventHandler);
            this._mapChildComp.set(nodeName,button);
            console.log("SetComp: ", nodeName);
        }
    }
    onClickEvent(event: Event, customEventData: string) {
        // The event here is a Touch object, and you can get the send node of the event by event.target
        const node = event.target as Node;
        // const button = node.getComponent(Button);
        console.log("Click button: ", node.name);
    }
}


