import eruda from 'eruda';
import { Address, GameFi, toNano, TonConnectUI, TonTransferRequest } from '@ton/cocos-sdk';

const queryStringToJSON = (queryString: string) => {
    if (!queryString)
        return new Map<string, string>();
    if (queryString.indexOf('?') > -1) {
        queryString = queryString.split('?')[1];
    }
    var pairs = queryString.split('&');
    var result = new Map<string, string>();
    // var result = {};
    pairs.forEach(function (pair: string) {
        let pairArr = pair.split('=');
        result.set(pairArr[0], decodeURIComponent(pairArr[1] || ''));
    });
    return result;
}

const {ccclass, property} = _decorator;

@ccclass('SceneManager')
export class SceneManager extends Component {

    //Server connection settings
    @property
    private serverURL: string = "localhost";
    @property
    private port: string = "2567";

    //UI Nodes
    @property({type: Node})
    private menuNode: Node | null = null;
    @property({type: Node})
    private lobbyNode: Node | null = null;
    @property({type: Node})
    private gameNode: Node | null = null;
    @property({type: Node})
    private endgameNode: Node | null = null;

    //Game Elements
    @property({type: Board})
    private board: Board | null = null;
    @property({type: Label})
    private statusText: Label | null = null;
    @property({type: Label})
    private resultsText: Label | null = null;
    @property({type: Label})
    private timerText: Label | null = null;
    @property({type: Label})
    private welcomeText: Label | null = null;
    @property({type: EditBox})
    private server: EditBox | null = null;
    @property({type: EditBox})
    private ebxBuyChip: EditBox | null = null;

    //local private variables
    private gameState: string = "MENU";
    private client: Colyseus.Client | null = null;
    private room: Colyseus.Room | null = null;
    private countdownInterval: any;

    
    private _cocosGameFi: GameFi;
    private _connectUI;
    private _bTonInit: boolean = false;
    @property(Label)
    connectLabel: Label;
    
    onLoad() {
        eruda.init();
        // console.log("InitData: ", WebApp.initData);
        // console.log("InitDataUnsafe: ", WebApp.initDataUnsafe);
        // console.log("WebApp: ", WebApp.platform);
        // // do verify data
        // let initData = queryStringToJSON(WebApp.initData);
        // let userData = {
        //     username: 'Friend'
        // }
        // if (initData.has("user"))
        //     userData = JSON.parse(initData.get("user") || "");
        let endpoint: string = `ws://${this.serverURL}:${this.port}`;
        console.log("Connect to ", endpoint);
        this.welcomeText!.string = 'Welcome, ' + "userData.username";
        this.client = new Colyseus.Client(endpoint);
        this.resetGame();

        let lastServer = localStorage.getItem("sv") || "ws://localhost:2567";
        this.server!.string = lastServer;
        this._initTonUI();
    }

    async _initTonUI() {

        let uiconnector = new TonConnectUI({
            manifestUrl: 'https://ton-connect.github.io/demo-dapp-with-wallet/tonconnect-manifest.json'
        });
        this._cocosGameFi = await GameFi.create({
            connector: uiconnector,
            network: 'testnet',
        });
        this._connectUI = this._cocosGameFi.walletConnector;

        const unsubscribeModal = this._connectUI.onModalStateChange(state => {
            console.log("model state changed! : ", state);

            this.updateConnect();
        });

        const unsubscribeConnectUI = this._connectUI.onStatusChange(info => {
            console.log("wallet info status changed : ", info);

            this.updateConnect();
        });

        this._bTonInit = true;
        this.updateConnect();
    }

    public isConnected(): boolean {
        if (!this._connectUI) {
            console.error("ton ui not inited!");
            return false;
        }
        return this._connectUI.connected;
    }

    private updateConnect() {
        if (this.isConnected()) {
            const address = this._connectUI.account.address;
            this.connectLabel.string = Address.parseRaw(address).toString( {testOnly: true, bounceable: false }).substring(0, 6) + '...';
        } else {
            this.connectLabel.string = "Connect";
        }
    }

    public async openModal() {
        if (!this._bTonInit) return;

        if (this.isConnected()) {
            this._connectUI.disconnect();
        } else {
            this._connectUI.openModal();
        }
    }

    onChangeServer() {
        let endpoint = this.server!.string;
        console.log("Change server: ", endpoint);
        localStorage.setItem("sv", endpoint);
        this.client = new Colyseus.Client(endpoint);
        this.resetGame();
    }

    resetGame() {
        this.gameState = "MENU";
        this.board!.initialize(this);
        this.handleGameState();
    }

    onEnable() {
        // systemEvent.on(SystemEvent.EventType.MOUSE_DOWN, this.handleMouseClick, this);
    }

    onDisable() {
        // this.node.off('mousedown', this.handleMouseClick);
    }

    handleGameState() {
        this.menuNode!.active = this.gameState == "MENU";
        this.lobbyNode!.active = this.gameState == "LOBBY";
        this.gameNode!.active = this.gameState == "GAME";
        this.endgameNode!.active = this.gameState == "ENDGAME"
    }

    // handleMouseClick(event: any){
    //     switch(this.gameState){
    //         case "MENU":
    //             {
    //                 this.gameState = "LOBBY";
    //                 this.handleGameState();
    //                 this.connect();
    //                 break;
    //             }
    //     }
    // }

    startGame() {
        switch (this.gameState) {
            case "MENU": {
                this.gameState = "LOBBY";
                this.handleGameState();
                this.connect();
                break;
            }
        }
    }

    async connect() {
        console.log("Joining game...");
        this.room = await this.client!.joinOrCreate("tictactoe");
        console.log('Colyseus.Step.1 connect server')

        let numPlayers = 0;
        this.room.state.players.onAdd((player, key) => {
            console.log(player, "has been added at", key);

            // add your player entity to the game world!

            numPlayers++;

            if (numPlayers === 2) {
                this.onJoin();
            }

            // // detecting changes on object properties
            // player.listen("field_name", (value, previousValue) => {
            //     console.log(value);
            //     console.log(previousValue);
            // });
        });

        this.room.onStateChange.once((state) => {
            console.log("Colyseus.onStateChange once: ", state);
        });

        this.room.onStateChange((state) => {
            console.log("Colyseus.onStateChange: ", state);
        });

        this.room.onLeave((code) => {
            console.log("Colyseus.onLeave:", code);
            this.resetGame();
        });

        this.room.state.board.onChange((value: number, index: number) => {
            console.log(`Colyseus.state.board.onChange ${value} -  ${index}`);
            const x = index % 3;
            const y = Math.floor(index / 3);
            this.board!.set(x, y, value);
        });

        const listener = this.room.state.listen("currentTurn", (currentValue: string, previousValue: string) => {
            console.log(`Colyseus.state.currentTurn is now ${currentValue}`);
            console.log(`Colyseus.state.previous value was: ${previousValue}`);
            // go to next turn after a little delay, to ensure "onJoin" gets called before this.
            setTimeout(() => this.nextTurn(currentValue), 10);
        });
        //if want to stop listen -> call listener();
        // listener();

        this.room.state.listen("draw", () => this.showEndgame("Draw!"));
        this.room.state.listen("winner", (sessionId: string) => this.showEndgame(this.room!.sessionId == sessionId ? "You win!" : "You lose!"));

        //khong vao day nua
        this.room.state.onChange((changes: any) => {
            console.log("Colyseus.state.onChange =>", changes);
        });

        this.room.onError.once(() => {
            this.showEndgame("And error has occurred, sorry!");
        });
    }

    showWinner(sessionId: string) {
        this.showEndgame(this.room!.sessionId == sessionId ? "You win!" : "You lose!");
    }

    showEndgame(message: string) {
        this.room!.leave()
        this.resultsText!.string = message;
        this.gameState = "ENDGAME";
        this.handleGameState();
        clearInterval(this.countdownInterval);
        //Reset afer a time
        setTimeout(() => {
            this.resetGame();
        }, 5000);
    }

    nextTurn(playerId: string) {
        if (playerId == this.room!.sessionId) {
            this.statusText!.string = "Your move!"
        } else {
            this.statusText!.string = "Opponent's turn..."
        }

        this.timerText!.string = "10";
        this.timerText!.color.set(Color.fromHEX(this.timerText!.color, '#000000'));
    }


    onJoin() {
        console.log("Joined game!");
        this.gameState = "GAME";
        this.handleGameState();
        this.countdownInterval = setInterval(this.turnCountdown.bind(this), 1000)
    }

    turnCountdown() {
        var currentNumber = parseInt(this.timerText!.string, 10) - 1

        if (currentNumber >= 0) {
            this.timerText!.string = currentNumber.toString()
        }

        let color = this.timerText!.color;
        if (currentNumber <= 3) {
            this.timerText!.color.set(Color.fromHEX(color, '#934e60'));
        } else {
            this.timerText!.color.set(Color.fromHEX(color, '#000000'));
        }

    }

    playerAction(pos: Vec2) {
        console.log("Colyseus.action from player => click", JSON.stringify(pos));
        this.room!.send("action", {x: pos.x, y: pos.y})
    }

    async onTouchBuyChip() {
        console.log("Buy chip: ", this.ebxBuyChip!.string);
        let chipValue = Number(this.ebxBuyChip.string);
        const tonValue = chipValue / 100; // fast test input 1
        const merchantAddress = '0QDOCfjls6KhM1NKyKEyCpySC2zP4cS5WSrAh1gSM0UU9r2D';
        if (this._cocosGameFi && this._cocosGameFi.walletConnector?.connected) {
            const tonTransferReq = {
                to: Address.parse(merchantAddress),
                amount: toNano(tonValue)
            } as TonTransferRequest;
            this._cocosGameFi.transferTon(tonTransferReq);
        }
    }
}