import { queryStringToJSON } from "../utils/Utils";

export class PlayerModule {
    public static _instance: PlayerModule;
    public static getInstance(): PlayerModule {
        if (!this._instance) {
            this._instance = new PlayerModule();
        }
        return this._instance;
    }

    public userInfo: any;
    public initData: any;
    public initDataObject: any;

    setInitData(initData) {
        this.initData = initData;
        this.initDataObject = queryStringToJSON(initData);
        const user = this.initDataObject.user;
        this.initDataObject.user = JSON.parse(user);
    }

    getInitData() {
        return this.initData;
    }

    getInitDataObject() {
        return this.initDataObject;
    }

    setUserInfo(userInfo) {
        this.userInfo = userInfo;
    }

    getUserInfo() {
        return this.userInfo;
    }

    getUsername() {
        return this.getUserInfo().user.username;
    }

    getUProfile() {
        return this.getUserInfo().profile;
    }

    getGold() {
        return this.getUProfile().gold;
    }

    addGold(goldAdded) {
        let currentGold = this.getGold();
        this.getUProfile().gold = currentGold + goldAdded;
    }

    getDiamond() {
        return this.getUProfile().diamond;
    }

    addDiamond(diamondAdded) {
        this.getUProfile().diamond += diamondAdded;
    }

    getUId() {
        return this.getUserInfo().id;
    }

    getAvatarUrl() {
        const userInitData = this.getInitDataObject().user;
        return userInitData.photo_url;
    }
}