export function queryStringToJSON(qs) {
    qs = qs || location.search.slice(1);

    var pairs = qs.split('&');
    var result = {};
    pairs.forEach(function(p) {
        var pair = p.split('=');
        var key = pair[0];
        var value = decodeURIComponent(pair[1] || '');

        if( result[key] ) {
            if( Object.prototype.toString.call( result[key] ) === '[object Array]' ) {
                result[key].push( value );
            } else {
                result[key] = [ result[key], value ];
            }
        } else {
            result[key] = value;
        }
    });

    return JSON.parse(JSON.stringify(result));
};

export function formatNumberFullSeparateThousand(number,separator = ",") {
    let numString = number.toString();
    var curIndex = numString.length - 3;
    while(curIndex > 0){
        numString = numString.substring(0, curIndex) + separator + numString.substring(curIndex, numString.length);
        curIndex -= 3;
    }
    return numString;
};